from pathlib import Path


def between(text: str, start: str, end: str, new: str, label: str) -> str:
    if text.count(start) != 1 or text.count(end) != 1:
        raise RuntimeError(f"{label}: markers are not unique")
    before, remainder = text.split(start, 1)
    _, after = remainder.split(end, 1)
    return before + new + end + after


path = Path("web/app/etl/app-shell-final.tsx")
text = path.read_text(encoding="utf-8")

institution_page = '''  const institutionPage = () => {
    const rows = filterRows(institutions,(item) => `${item.code} ${item.name} ${item.type} ${item.region}`);
    const selected = institutions.find((item) => item.id === selectedInstitutionId);
    return <><PageHeader page="institutions" actions={<PButton permission="institution.create" tone="primary" icon={<PlusOutlined/>} onClick={() => openCreate("institution")}>新增机构</PButton>}/><SearchBar query={query} setQuery={setQuery} placeholder="搜索机构编码、名称、类型"/><Card><Table headers={["机构","类型","等级","区域","关联资源","状态","操作"]} rows={rows.map((item) => { const relatedInstances = systemInstances.filter((instance) => instance.institutionIds.includes(item.id)); const relatedRoutes = routes.filter((route) => route.deletedAt === null && route.institutionIds.includes(item.id)); const relatedTasks = tasks.filter((task) => task.deletedAt === null && task.institutionId === item.id); return [<button type="button" key="c" className="link-cell" onClick={() => setSelectedInstitutionId(item.id)}><strong>{item.name}</strong><small>{item.code}</small></button>,item.type,item.level,item.region,<span key="r"><strong>{relatedInstances.length} 实例 / {relatedRoutes.length} 链路 / {relatedTasks.length} 任务</strong><small>点击机构查看关联详情</small></span>,<span key="s" className="state"><Badge value={item.status}/>{can("institution.status") && <Toggle checked={item.status === "ENABLED"} onChange={() => ask("变更机构状态",`确认${item.status === "ENABLED" ? "停用" : "启用"} ${item.name}？`,() => { setInstitutions((items) => items.map((row) => row.id === item.id ? {...row,status:row.status === "ENABLED" ? "DISABLED" : "ENABLED"} : row)); recordAudit("institution.status","INSTITUTION_STATUS_CHANGE",item.id,"SUCCESS",item.status === "ENABLED" ? "停用" : "启用"); })} label="切换机构状态"/>}</span>,<div key="a" className="row-actions"><Button tone="ghost" onClick={() => setSelectedInstitutionId(item.id)}>详情</Button><PButton permission="institution.update" tone="ghost" icon={<EditOutlined/>} onClick={() => openEdit("institution",item.code,{code:item.code,name:item.name,type:item.type,level:item.level,region:item.region,status:item.status,description:item.description})}>编辑</PButton><PButton permission="institution.delete" tone="ghost" icon={<DeleteOutlined/>} onClick={() => { if (relatedInstances.length || relatedRoutes.length || relatedTasks.length) return setToast("机构仍被实例、Route 或 Task 引用，只能停用"); ask("删除机构",`确认删除 ${item.name}？`,() => { setInstitutions((items) => items.filter((row) => row.id !== item.id)); recordAudit("institution.delete","INSTITUTION_DELETE",item.id,"SUCCESS",item.name); },true,"确认删除"); }}>删除</PButton></div>]; })}/></Card>{selected && <Card title={`机构关联详情 · ${selected.name}`} actions={<Button tone="ghost" onClick={() => setSelectedInstitutionId(null)}>关闭</Button>}><div className="grid-2"><div><h3 className="section-title">业务系统实例</h3><Table headers={["实例","类型","状态"]} rows={systemInstances.filter((item) => item.institutionIds.includes(selected.id)).map((item) => [item.name,item.systemType,<Badge key="s" value={item.status}/>])}/></div><div><h3 className="section-title">采集链路 / 任务</h3><Table headers={["类型","对象","Dataset"]} rows={[...routes.filter((item) => item.deletedAt === null && item.institutionIds.includes(selected.id)).map((item) => ["Route",item.id,item.datasetCode]),...tasks.filter((item) => item.deletedAt === null && item.institutionId === selected.id).map((item) => ["Task",item.id,item.datasetCode])]}/></div></div></Card>}</>;
  };

'''
